package uk.ac.ravensbourne.casevault.security;

import java.util.UUID; import org.springframework.security.authentication.*; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import uk.ac.ravensbourne.casevault.audit.PersistentAuditService; import uk.ac.ravensbourne.casevault.domain.*; import uk.ac.ravensbourne.casevault.repository.UserAccountRepository;
/** Performs constant-work-ish account lookup, lockout accounting and generic authentication failures (CWE-204/CWE-307). */
@Component public class CaseVaultAuthenticationProvider implements AuthenticationProvider {
 private static final String DUMMY_HASH="$argon2id$v=19$m=19456,t=3,p=1$MTIzNDU2Nzg5MDEyMzQ1Ng$9e8CS1jw1ILi62dxdfyJrY0TCzO7ujQPXd4ix/i1Nl0";
 private final UserAccountRepository users; private final PasswordEncoder encoder; private final PersistentAuditService audit;
 public CaseVaultAuthenticationProvider(UserAccountRepository u,PasswordEncoder e,PersistentAuditService a){users=u;encoder=e;audit=a;}
 @Override @Transactional(noRollbackFor=BadCredentialsException.class) public Authentication authenticate(Authentication authentication){String email=String.valueOf(authentication.getName()).trim().toLowerCase();String password=String.valueOf(authentication.getCredentials());var account=users.findByEmail(email);boolean matches=encoder.matches(password,account.map(UserAccount::getPasswordHash).orElse(DUMMY_HASH));if(account.isEmpty()||!matches||!account.get().isEnabled()||account.get().isLocked()){account.ifPresent(u->{u.registerFailure();if(u.isLocked())audit.record(UserPrincipal.from(u),"ACCOUNT_LOCKED","ACCOUNT",u.getId(),"account-locked");});audit.record(account.map(UserPrincipal::from).orElse(null),"LOGIN_FAILURE","ACCOUNT",account.map(UserAccount::getId).orElse(null),"login-failure");throw new BadCredentialsException("Invalid credentials");}var user=account.get();user.registerSuccess();var principal=UserPrincipal.from(user);audit.record(principal,"LOGIN_SUCCESS","ACCOUNT",user.getId(),"login-success");return UsernamePasswordAuthenticationToken.authenticated(principal,null,principal.getAuthorities());}
 @Override public boolean supports(Class<?> c){return UsernamePasswordAuthenticationToken.class.isAssignableFrom(c);} }
